ADukeBlasterBolt* ADukeBlasterBolt::Fire(UWorld* World, AActor* Shooter, const FVector& Start, const FVector& Direction, float InDamage, float Speed, FLinearColor Color)
{
	if (!World) return nullptr;
	FActorSpawnParameters P;
	P.Owner = Shooter;
	P.Instigator = Cast<APawn>(Shooter);
	P.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
	const FVector Dir = Direction.GetSafeNormal();
	ADukeBlasterBolt* B = World->SpawnActor<ADukeBlasterBolt>(ADukeBlasterBolt::StaticClass(), Start, Dir.Rotation(), P);
	if (!B) return nullptr;
	B->Damage = InDamage;
	B->BoltColor = Color;
	B->ApplyLook();
	if (Shooter) B->Collision->IgnoreActorWhenMoving(Shooter, true);
	B->Movement->InitialSpeed = Speed;
	B->Movement->MaxSpeed = Speed;
	B->Movement->Velocity = Dir * Speed;
	return B;
}

void ADukeBlasterBolt::OnBoltHit(UPrimitiveComponent* HitComp, AActor* OtherActor, UPrimitiveComponent* OtherComp, FVector NormalImpulse, const FHitResult& Hit)
{
	if (ImpactTime >= 0.f) return;
	if (OtherActor && OtherActor != GetOwner() && Damage > 0.f)
	{
		AController* InstigatorController = GetInstigator() ? GetInstigator()->GetController() : nullptr;
		UGameplayStatics::ApplyPointDamage(OtherActor, Damage, GetActorForwardVector(), Hit, InstigatorController, GetOwner(), UDamageType::StaticClass());
	}
	if (USoundBase* S = LoadObject<USoundBase>(nullptr, BoltImpactSound))
		UGameplayStatics::PlaySoundAtLocation(this, S, Hit.ImpactPoint, 0.6f, FMath::FRandRange(0.9f, 1.1f));
	// impact flash: stop, hide the bolt, flare the light for a few frames
	ImpactTime = GetWorld()->GetTimeSeconds();
	Movement->StopMovementImmediately();
	SetActorLocation(Hit.ImpactPoint + Hit.ImpactNormal * 8.f);
	Core->SetVisibility(false);
	Glow->SetVisibility(false);
	Collision->SetCollisionEnabled(ECollisionEnabled::NoCollision);
	Light->SetIntensity(14000.f);
	Light->SetAttenuationRadius(220.f);
	Light->SetLightColor(FLinearColor(1.f, 0.35f, 0.15f));
	SetLifeSpan(0.12f);
}

void ADukeBlasterBolt::Tick(float DeltaSeconds)
{
	Super::Tick(DeltaSeconds);
	if (ImpactTime >= 0.f)
	{
		const float K = FMath::Clamp(1.f - (GetWorld()->GetTimeSeconds() - ImpactTime) / 0.12f, 0.f, 1.f);
		Light->SetIntensity(14000.f * K);
	}
}
